import asyncio
from functools import wraps
from urllib.parse import urlparse

from asgiref.sync import async_to_sync, sync_to_async

from django.conf import settings
from django.contrib.auth import REDIRECT_FIELD_NAME
from django.core.exceptions import PermissionDenied
from django.shortcuts import resolve_url


def user_passes_test(
    test_func, login_url=None, redirect_field_name=REDIRECT_FIELD_NAME
):
    def decorator(view_func):
        def _redirect_to_login(request):
            path = request.build_absolute_uri()
            resolved_login_url = resolve_url(login_url or settings.LOGIN_URL)
            login_scheme, login_netloc = urlparse(resolved_login_url)[:2]
            current_scheme, current_netloc = urlparse(path)[:2]
            if (not login_scheme or login_scheme == current_scheme) and (
                not login_netloc or login_netloc == current_netloc
            ):
                path = request.get_full_path()
            from django.contrib.auth.views import redirect_to_login

            return redirect_to_login(path, resolved_login_url, redirect_field_name)

        if asyncio.iscoroutinefunction(view_func):
            async def _view_wrapper(request, *args, **kwargs):
                auser = await request.auser()
                if asyncio.iscoroutinefunction(test_func):
                    test_pass = await test_func(auser)
                else:
                    test_pass = await sync_to_async(test_func)(auser)

                if test_pass:
                    return await view_func(request, *args, **kwargs)
                return _redirect_to_login(request)
        else:
            def _view_wrapper(request, *args, **kwargs):
                if asyncio.iscoroutinefunction(test_func):
                    test_pass = async_to_sync(test_func)(request.user)
                else:
                    test_pass = test_func(request.user)

                if test_pass:
                    return view_func(request, *args, **kwargs)
                return _redirect_to_login(request)

        _view_wrapper.login_url = login_url
        _view_wrapper.redirect_field_name = redirect_field_name

        return wraps(view_func)(_view_wrapper)

    return decorator


def login_required(function=None, redirect_field_name=REDIRECT_FIELD_NAME, login_url=None):
    actual_decorator = user_passes_test(
        lambda u: u.is_authenticated,
        login_url=login_url,
        redirect_field_name=redirect_field_name,
    )
    if function:
        return actual_decorator(function)
    return actual_decorator


def login_not_required(view_func):
    """
    Decorator for views that allows access to unauthenticated requests.
    """
    view_func.login_required = False
    return view_func


def permission_required(perm, login_url=None, raise_exception=False):
    if isinstance(perm, str):
        perms = (perm,)
    else:
        perms = perm

    def decorator(view_func):
        if asyncio.iscoroutinefunction(view_func):

            async def check_perms(user):
                if await sync_to_async(user.has_perms)(perms):
                    return True
                if raise_exception:
                    raise PermissionDenied
                return False

        else:
            def check_perms(user):
                if user.has_perms(perms):
                    return True
                if raise_exception:
                    raise PermissionDenied
                return False

        return user_passes_test(check_perms, login_url=login_url)(view_func)

    return decorator


# Adding the new role_required decorator
def role_required(*allowed_roles):
    """
    Decorator to check if the user has one of the allowed roles.
    Usage:
        @role_required('admin', 'officer', 'researcher')
        def some_view(request, org_id):
            ...
    """
    def decorator(view_func):
        if asyncio.iscoroutinefunction(view_func):
            async def _wrapped_view(request, *args, **kwargs):
                auser = await request.auser()
                role = await sync_to_async(lambda: auser.role)
                if role in allowed_roles:
                    return await view_func(request, *args, **kwargs)
                else:
                    raise PermissionDenied("You do not have permission to access this page.")
        else:
            def _wrapped_view(request, *args, **kwargs):
                if request.user.role in allowed_roles:
                    return view_func(request, *args, **kwargs)
                else:
                    raise PermissionDenied("You do not have permission to access this page.")
        return wraps(view_func)(_wrapped_view)

    return decorator